doc.codeblock:
{
  "version": 3,
  "items": [
    {
      "kind": "hold",
      "id": "lctrl",
      "title": "左 Control",
      "mods": ["lctrl"],
      "keys": {
        "t": { "type": "note", "text": "这个键留给输入法" },
        "b": { "type": "app", "bundleID": "com.tencent.wechat" },
        "v": { "type": "key", "mods": ["lcmd"], "key": "v" },
        "x": { "type": "block", "text": "不在这里退出" }
      },
      "onRelease": { "type": "note", "text": "只按左 Ctrl" },
      "onDoubleTap": { "type": "app", "bundleID": "com.apple.finder" },
      "window": 350
    }
  ]
}

{
  "version": 3,
  "bindings": [
    { "mods": ["lctrl"], "key": "t", "action": { "type": "note", "text": "这个键留给输入法" } },
    { "mods": ["lctrl"], "key": "b", "action": { "type": "app", "bundleID": "com.tencent.wechat" } },
    { "mods": ["lctrl"], "gesture": "single", "action": { "type": "note", "text": "只按左 Ctrl" } },
    { "mods": ["lalt"], "key": "v", "action": { "type": "key", "mods": ["lcmd"], "key": "v" } }
  ]
}
